                Id, 
                Name, 
                OwnerId, 
                Primary_Contact__c, 
            from Property__c 
            where Id = :propertyId limit 1
        ];
        Proposal__c proposal = new Proposal__c(
            Name =  property.Name, 
            OwnerId  =  property.ownerid, 
            Property__c = property.Id, 
            Client__c = property.Primary_Contact__c, 
