        String editName='/e?retURL=%2F'+proposal.Id;
        pref = new PageReference(sServerName + proposal.Id+editName); 
        pref.setRedirect(true);

        return pref;

    } 

    public PageReference back(){
        PageReference pref = new PageReference('/' + propertyId);
        pref.setRedirect(true);
        return pref;
    }      
}

